import {sha256,sha512} from '../assets/vendor/sha2.js';
self.onmessage=async({data})=>{try{const hash=(data.algorithm==='SHA-512'?sha512:sha256).create(),reader=data.file.stream().getReader();let loaded=0,last=0;while(true){const {done,value}=await reader.read();if(done)break;hash.update(value);loaded+=value.byteLength;if(loaded-last>1048576){last=loaded;self.postMessage({progress:loaded});}}const digest=Array.from(hash.digest(),x=>x.toString(16).padStart(2,'0')).join('');self.postMessage({digest});}catch(e){self.postMessage({error:e.message||'Could not hash this file.'});}};
